const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Rectangle([113.8, 22.1, 114.5, 22.6]); // Bounding box for Hong Kong
  const startDate1 = '2020-02-10';
  const endDate1 = '2020-02-25';
  const startDate2 = '2020-04-20';
  const endDate2 = '2020-05-12';
  const band = 'tropospheric_NO2_column_number_density';

  // 2. Data Acquisition & Check
  const getMeanNO2 = (startDate, endDate) => {
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterBounds(aoi)
      .filterDate(startDate, endDate)
      .select([band, 'qa_value']);

    // Mask for data quality. A qa_value > 0.75 is recommended.
    const maskedCollection = collection.map(function(image) {
      const qaMask = image.select('qa_value').gt(0.75);
      return image.updateMask(qaMask);
    });

    return {
        collection: maskedCollection,
        imageCount: collection.size()
    };
  };

  const period1Data = getMeanNO2(startDate1, endDate1);
  const period2Data = getMeanNO2(startDate2, endDate2);

  const imageCount1 = period1Data.imageCount.getInfo();
  const imageCount2 = period2Data.imageCount.getInfo();

  console.log(`Images found for Feb 2020: ${imageCount1}`);
  console.log(`Images found for Apr-May 2020: ${imageCount2}`);

  if (imageCount1 === 0 || imageCount2 === 0) {
    console.log("Evidence: No images found for one or both periods.");
    console.log("A: No");
    return;
  }

  const meanImage1 = period1Data.collection.select(band).mean();
  const meanImage2 = period2Data.collection.select(band).mean();

  // 3. Processing & Calculation
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = meanImage1.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2 = meanImage2.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  // Fetch results asynchronously
  const stats1Info = await ee.data.computeValue(stats1);
  const stats2Info = await ee.data.computeValue(stats2);

  const mean1 = stats1Info[`${band}_mean`];
  const count1 = stats1Info[`${band}_count`];
  const mean2 = stats2Info[`${band}_mean`];
  const count2 = stats2Info[`${band}_count`];

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Evidence: No valid pixels after QA masking for one or both periods.`);
    console.log(`Feb 2020 Valid Pixels: ${count1}`);
    console.log(`Apr-May 2020 Valid Pixels: ${count2}`);
    console.log("C2: No Valid Pixels");
    return;
  }

  if (mean1 == null || mean2 == null) {
      console.log("Evidence: Calculation resulted in a null value.");
      console.log(`Feb 2020 Mean: ${mean1}`);
      console.log(`Apr-May 2020 Mean: ${mean2}`);
      console.log("C3: Calculation Failure");
      return;
  }

  // The units are mol/m^2. Multiply by 1e6 for a more readable micromol/m^2.
  console.log(`Evidence Feb 2020 Mean NO2 (umol/m^2): ${(mean1 * 1e6).toFixed(2)}`);
  console.log(`Evidence Apr-May 2020 Mean NO2 (umol/m^2): ${(mean2 * 1e6).toFixed(2)}`);

  if (mean2 > mean1) {
    console.log("B: No");
  } else {
    console.log("A: Yes");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
